transformation:
(text) => {
                          const clean = text.replace(/[^\d.]/g, "");
                          // A reading and a reason never go together.
                          if (clean) {
                            setFieldValue(
                              "removal.noReadingReason",
                              makeEmptySelectWithOther(),
                            );
                          }
                          setFieldValue(
                            isPrepaidReading
                              ? "removal.tokenReading"
                              : "removal.meterReading",
                            clean,
                          );
                        }
